BEGIN;
CREATE TABLE IF NOT EXISTS artist_balances (artist_id uuid PRIMARY KEY REFERENCES artist_profiles(id) ON DELETE CASCADE,available_minor bigint NOT NULL DEFAULT 0,pending_minor bigint NOT NULL DEFAULT 0,currency char(3) NOT NULL DEFAULT 'EUR',updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS royalty_ledger (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),artist_id uuid NOT NULL REFERENCES artist_profiles(id) ON DELETE CASCADE,track_id uuid REFERENCES tracks(id) ON DELETE SET NULL,entry_type varchar(40) NOT NULL,amount_minor bigint NOT NULL,currency char(3) NOT NULL DEFAULT 'EUR',reference_public_id varchar(32),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS royalty_artist_idx ON royalty_ledger(artist_id,created_at DESC);
CREATE TABLE IF NOT EXISTS daily_platform_metrics (metric_date date PRIMARY KEY,streams bigint NOT NULL DEFAULT 0,active_listeners bigint NOT NULL DEFAULT 0,active_artists bigint NOT NULL DEFAULT 0,gross_revenue_minor bigint NOT NULL DEFAULT 0,payouts_minor bigint NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE VIEW admin_finance_summary AS SELECT COALESCE((SELECT sum(amount_minor) FROM payments WHERE status='COMPLETED'),0)::bigint settled_revenue_minor,COALESCE((SELECT sum(amount_minor) FROM payments WHERE status='PENDING'),0)::bigint pending_revenue_minor,COALESCE((SELECT sum(amount_minor) FROM payouts WHERE status='COMPLETED'),0)::bigint paid_out_minor,COALESCE((SELECT sum(amount_minor) FROM payouts WHERE status='PENDING'),0)::bigint pending_payout_minor,(SELECT count(*) FROM payments)::bigint payment_count,(SELECT count(*) FROM payouts)::bigint payout_count;
CREATE OR REPLACE VIEW admin_platform_summary AS SELECT (SELECT count(*) FROM accounts WHERE status='ACTIVE')::bigint active_accounts,(SELECT count(*) FROM artist_profiles)::bigint artists,(SELECT count(*) FROM business_profiles)::bigint businesses,(SELECT count(*) FROM tracks)::bigint tracks,(SELECT count(*) FROM releases)::bigint releases,(SELECT count(*) FROM stream_events WHERE counted)::bigint streams,(SELECT count(*) FROM subscriptions WHERE status='ACTIVE')::bigint active_subscriptions,(SELECT count(*) FROM risk_cases WHERE status<>'RESOLVED')::bigint open_risk_cases,(SELECT count(*) FROM support_tickets WHERE status NOT IN ('RESOLVED','CLOSED'))::bigint open_support_tickets;
COMMIT;
